// 1. Obtener texto de Gemini
const rawText = $input.first().json.text
const cleaned = rawText.replace(/```json|```/g, '').trim();

let result;

// 2. Intentar parsear el JSON
try {
  result = JSON.parse(cleaned);
} catch (error) {
  result = {
    compra: null,
    categoria: null,
    valor: null,
    fecha: null,
    es_gasto_real: false // Asumimos que no es gasto si falló catastróficamente
  };
}

// 3. RECUPERAR EL ORIGEN (Source)
// Esto es vital: buscamos en el nodo unificador si vino de 'android' o 'telegram'
try {
  result = JSON.parse(cleaned);

  // MANTENER INTENCIÓN Y MEDIO DE PAGO
  // Si Gemini no devolvió medio_pago, lo forzamos a null para evitar undefined
  if (!result.medio_pago) result.medio_pago = null;
  if (!result.intencion) result.intencion = 'transaccion'; // Default por seguridad

} catch (error) {
    // Si falla, por defecto asumimos telegram para que te avise el error
    result.source = 'telegram';
}

return [{
  json: result
}];

const plan = $input.first().json; // Datos del plan recién creado (necesitamos el ID)
const gemini = $('Seteo de campos').first().json; // Datos originales
const userId = $('Identificar usuario').first().json.id;
const cantidad = gemini['Cantidad de cuotas']
const montoCuota = gemini['Monto total'] / cantidad;
const fechaInicioPagos = new Date($('Calculadora de vencimiento').first().json.FechaRealPago)

const transacciones = [];

for (let i = 0; i < cantidad; i++) {
  let fechaPago = new Date(fechaInicioPagos);
  fechaPago.setMonth(fechaPago.getMonth() + i); // Sumamos meses desde el primer pago

  transacciones.push({
    user_id: userId,
    description: `${gemini['Compra']} (Cuota ${i + 1}/${cantidad})`,
    category: gemini.categoria,
    amount: Math.abs(montoCuota), // Siempre negativo
    date: fechaPago.toISOString(), // Formato ISO para Postgres
    type: 'expense',
    payment_method: 'Credit Card', // Asumimos tarjeta si es cuota
    installment_plan_id: plan.id // Vinculamos al padre
  });
}

return transacciones;

// Obtener el input inmediato (para ver si es Webhook)
const item = $input.first();

// --- CASO 1: Viene del WEBHOOK (Android/MacroDroid) ---
// Verificamos si la entrada inmediata tiene "body" (típico de Webhook)
if (item.json.body) {
  return {
    text: item.json.body.mensaje, // Asegurate que en MacroDroid mandaste la variable "mensaje"
    source: 'android',
    chat_id: 1995566176 // Tu ID fijo que pusiste
  };
}

// --- CASO 2: Viene de TELEGRAM ---
// Si no es webhook, asumimos que es Telegram.
// PERO, como venimos de un nodo de "Respuesta", tenemos que ignorar el input inmediato
// y buscar los datos "aguas arriba" en el nodo Trigger original.

try {
  // Accedemos directamente a los datos del nodo "Trigger mensaje"
  // Usamos try/catch por si acaso el nodo no existe o no corrió


  if ($('Telegram Trigger').first().json.message) {
    return {
      text: $('Telegram Trigger').first().json.message.text,
      source: 'telegram',
      chat_id: ($('Telegram Trigger').first().json.message.from.id).toString()
    };
  }
} catch (error) {
  // Si da error aquí, es porque el nodo Trigger no se ejecutó 
  // (probablemente estamos en una prueba aislada o algo raro)
  console.log("No se encontraron datos del Trigger de Telegram");
}

// Si nada funcionó:
return { text: '', error: 'No se detectó origen válido' };

