// 2. INICIALIZAR FECHAS
const fechaCompra = new Date($input.first().json.Fecha);
let fechaPagoReal = new Date(fechaCompra);

// 3. LÓGICA DE CRÉDITO (Cash Flow Real)
if ($input.first().json['Tipo de Medio de pago'] === 'credit') {
  const diaCompra = fechaCompra.getDate();

  // Paso A: Determinar si salta al próximo resumen
  if (diaCompra > $input.first().json['Día de cierre']) {
    fechaPagoReal.setMonth(fechaPagoReal.getMonth() + 1);
  }

  // Paso B: Determinar si el pago cae al mes siguiente del cierre
  // (Si vence el 5 y cierra el 25, paga al mes siguiente)
  if ($input.first().json['Día de vencimiento'] < $input.first().json['Día de cierre']) {
    fechaPagoReal.setMonth(fechaPagoReal.getMonth() + 1);
  }

  // Paso C: Fijar el día exacto de PAGO
  fechaPagoReal.setDate($input.first().json['Día de vencimiento']);
}

// 4. RETORNAR
return {
  Compra: $input.first().json.Compra,
  Categoría: $input.first().json['Categoría'],
  Valor:$input.first().json.Valor,
  payment_method_id: $input.first().json['Id Medio de pago'],
  FechaRealPago: fechaPagoReal.toISOString().split('T')[0]
};

