const raw = $input.first().json.precio_texto; // Ej: "1.050,50"

if (!raw) {
  throw new Error("No se pudo extraer el precio. Revisa el selector CSS.");
}

// 1. Limpieza de texto (String)
const textoLimpio = raw
  .replace(/[^0-9,]/g, '') // Borra todo lo que NO sea número o coma (borra el punto de mil y el $)
  .replace(',', '.');      // Cambia la coma decimal por punto (formato JS)

// 2. Conversión a Número (Float)
// Usamos 'let' porque vamos a modificar esta variable si entra en la regla
let precioFinal = parseFloat(textoLimpio);

// 3. Regla Heurística (ONs/Bonos)
// Recuperamos el tipo del nodo anterior
const tipoActivo = $('El Clasificador').first().json.type;

if (tipoActivo === 'on' || tipoActivo === 'bond') {
  // Si vale más de 20 (ej: 109.90), asumimos que es precio "cada 100"
  if (precioFinal > 20) {
    precioFinal = precioFinal / 100;
  }
}

return {
  ticker: $('El Clasificador').first().json.ticker, // Mantenemos el ticker original
  last_price: precioFinal
};

const text = $('Telegram Trigger').first().json.message.text || "";

// Separamos por espacios y limpiamos bordes
const parts = text.trim().split(/\s+/);

// VALIDACIÓN ESTRICTA
// 1. parts[0] debe ser "/start"
// 2. parts[1] debe existir y tener longitud de UUID (36 chars)
//    (Ej: 06e2ba95-3025-4aed-be17-410a88cc1eb4)

if (parts[0] === '/start' && parts.length >= 2 && parts[1].length === 36) {
  return {
    isValid: true,
    token: parts[1], // El UUID limpio
    chatId: $('Telegram Trigger').first().json.message.chat.id,
    firstName: $('Telegram Trigger').first().json.message.chat.first_name
  };
} else {
  // Si dice "gaste 4000 en un sanguche", cae acá
  return { isValid: false }; 
}

