const items = $input.all();
let texto = "¡Excelente! Configuración terminada. 🚀\n\n<b>Tus medios de pago:</b>\n";

for (const item of items) {
  const data = item.json;
  let icono = "💳";
  if (data.type === 'cash') icono = "💵";
  if (data.type === 'debit') icono = "🏧";

  texto += `${icono} <b>${data.name}</b>`;

  if (data.type === 'credit') {
    texto += ` (Cierra: ${data.default_closing_day}, Vence: ${data.default_payment_day})`;
  }
  texto += "\n";
}

return { id: $('Router').first().json.id,text: texto };

// 1. Obtenemos la respuesta cruda de Gemini
// Ajusta 'text' si tu nodo Gemini devuelve el contenido en otro campo (ej: 'output', 'content')
const rawResponse = $input.first().json.content.parts[0].text || $input.first().json.output || "";

// 2. Limpieza Quirúrgica 🧹
// A veces Gemini devuelve: ```json { ... } ``` o texto antes/después.
// Esta Regex busca lo que está entre el primer '{' y el último '}'
const jsonMatch = rawResponse.match(/\{[\s\S]*\}/);

let finalJson = {};

if (jsonMatch) {
  try {
    // 3. Intentamos parsear lo que encontramos
    finalJson = JSON.parse(jsonMatch[0]);
  } catch (error) {
    // Si falla, devolvemos un error controlado
    finalJson = { error: "No se pudo parsear el JSON", raw: rawResponse };
  }
} else {
  // Si no encontró llaves {}, devolvemos error
  finalJson = { error: "No se encontró estructura JSON", raw: rawResponse };
}

// 4. Retornamos el objeto limpio para que el resto del flujo lo use directo
return  finalJson;

const text = $('Telegram Trigger').first().json.message.text;

// Palabras de relleno a eliminar (case insensitive)
// Borra: "la", "el", "mi", "tarjeta", "de", "banco", "uso"
const cleanText = text
  .replace(/\b(el|la|los|las|un|una|mi|mis|tarjeta|tarjetas|de|del|banco|uso|quiero)\b/gi, '')
  .replace(/\s+/g, ' ') // Elimina espacios dobles
  .trim();

return { 
  original: text,
  termino_busqueda: cleanText 
};

