const items = $input.all();

// Lista para el Prompt (Texto)
const listaPrompt = items.map(i => {
   return `${i.json.name}`;
}).join(', ');

// Diccionario de IDs (Nuevo!)
// Crea algo así: { "Supermercado": "uuid-123...", "Ropa": "uuid-456..." }
const mapaIds = {};
items.forEach(i => {
    mapaIds[i.json.name] = i.json.id;
});

return [{
  json: {
    categories_prompt: listaPrompt,
    categories_map: mapaIds, // Pasamos el mapa hacia adelante
    user_id: items[0].json.user_id
  }
}];

// 1. Obtenemos el texto FINAL que aprobó el usuario.
// Asegúrate de traer el campo 'custom_categories_prompt' del nodo 'Identificar usuario' 
// o del nodo que actualizó el prompt por última vez.
const promptText = $input.first().json.custom_categories_prompt

const userId = $('Identificar usuario').first().json.id;

// 2. Regex para desarmar el formato: "🛒 *Nombre*: Descripción"
// Esta regex busca: Emoji opcional -> Nombre entre asteriscos -> Separador -> Descripción
const regex = /(?:^|\n)([^a-zA-Z0-9\s]*)\s*\*?([^*]+)\*?\s*[:|-]\s*([^\n]+)/g;

let match;
const categories = [];

// 3. Iteramos todas las coincidencias
while ((match = regex.exec(promptText)) !== null) {
    const emoji = match[1].trim(); // Grupo 1: Emoji
    const name = match[2].trim();  // Grupo 2: Nombre
    const desc = match[3].trim();  // Grupo 3: Descripción

    categories.push({
        user_id: userId,
        name: name,
        emoji: emoji || '📦', // Emoji default si no encuentra
        description: desc
    });
}

// 4. Devolvemos el array listo para insertar
return {
    json: {
        categories_to_insert: categories
    }
};

// 1. Obtenemos el output de Gemini
const rawInput = $input.first().json.content.parts[0].text 

// 2. LIMPIEZA ROBUSTA: Quitamos markdown (```json ... ```) y espacios extras
const cleanJson = rawInput
    .replace(/```json/g, '') // Quita inicio de bloque
    .replace(/```/g, '')     // Quita fin de bloque
    .trim();                 // Quita espacios

let categories = [];
try {
    categories = JSON.parse(cleanJson);
} catch (e) {
    // Si falla el parseo, devolvemos array vacío o un fallback
    console.log("Error parseando JSON de Gemini:", e);
    categories = [];
}

// 3. GENERAR LAS DOS VERSIONES

// Versión FULL: Para la Base de Datos (Postgres)
// Usamos description_full para que Gemini tenga mucho contexto en el futuro
const fullText = categories.map(c => 
    `${c.emoji} *${c.name}*: ${c.description_full}`
).join('\n');

// Versión SHORT: Para Telegram (Chat)
// Usamos description_short para que sea legible y NO corte con "..."
const shortText = categories.map(c => 
    `${c.emoji} <b>${c.name}</b>: ${c.description_short}`
).join('\n');


return {
    json: {
        categories_parsed: categories,   // Para debug
        formatted_text_full: fullText,   // -> Mapear a Postgres
        formatted_text_short: shortText  // -> Mapear a Telegram
    }
};

